from pathlib import Path
import sys


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    return text.replace(old, new, 1)


def main(path: str) -> None:
    p = Path(path)
    s = p.read_text(encoding="utf-8-sig")

    s = replace_once(s, 'APP_VERSION = "1.11.14"', 'APP_VERSION = "1.11.15"', 'version')

    # Reusable hover-help control. The small ? icon deliberately uses a normal
    # Tk/ttk widget rather than a platform-specific dependency so the portable
    # Windows build remains self-contained.
    marker = '\n\n@dataclass\nclass Rule:\n'
    helper = '''\n\nclass HoverHelp:\n    \"\"\"Show a short explanation when the pointer rests over a ? icon.\"\"\"\n    def __init__(self, widget, text: str, delay_ms: int = 300):\n        self.widget = widget\n        self.text = text\n        self.delay_ms = delay_ms\n        self._after_id = None\n        self._tip = None\n        widget.bind(\"<Enter>\", self._schedule, add=\"+\")\n        widget.bind(\"<Leave>\", self._hide, add=\"+\")\n        widget.bind(\"<ButtonPress>\", self._hide, add=\"+\")\n\n    def _schedule(self, _event=None):\n        self._cancel()\n        self._after_id = self.widget.after(self.delay_ms, self._show)\n\n    def _cancel(self):\n        if self._after_id is not None:\n            try:\n                self.widget.after_cancel(self._after_id)\n            except Exception:\n                pass\n            self._after_id = None\n\n    def _show(self):\n        self._after_id = None\n        if self._tip is not None or not self.text:\n            return\n        x = self.widget.winfo_rootx() + self.widget.winfo_width() + 8\n        y = self.widget.winfo_rooty() + self.widget.winfo_height() + 2\n        tip = tk.Toplevel(self.widget)\n        tip.wm_overrideredirect(True)\n        tip.wm_geometry(f\"+{x}+{y}\")\n        ttk.Label(\n            tip, text=self.text, justify=\"left\", wraplength=360,\n            padding=(9, 7), relief=\"solid\", borderwidth=1\n        ).pack()\n        self._tip = tip\n\n    def _hide(self, _event=None):\n        self._cancel()\n        if self._tip is not None:\n            try:\n                self._tip.destroy()\n            except Exception:\n                pass\n            self._tip = None\n\n\ndef help_icon(parent, text: str):\n    icon = ttk.Label(parent, text=\"?\", width=2, anchor=\"center\", relief=\"groove\", cursor=\"question_arrow\")\n    icon._hover_help = HoverHelp(icon, text)\n    return icon\n\n\ndef help_action(parent, text: str, command, help_text: str, side: str = \"left\", padx=3):\n    holder = ttk.Frame(parent)\n    holder.pack(side=side, padx=padx, pady=2)\n    button = ttk.Button(holder, text=text, command=command)\n    button.pack(side=\"left\")\n    help_icon(holder, help_text).pack(side=\"left\", padx=(2, 0))\n    return button\n'''
    s = replace_once(s, marker, helper + marker, 'hover help helper')

    old_main_actions = '''        actions = ttk.Frame(controls); actions.pack(fill="x")\n        ttk.Button(actions, text="Save rule from selected", command=lambda d=direction: self.assign_rule_selected(d)).pack(side="left", padx=3)\n        ttk.Button(actions, text="Assign once", command=lambda d=direction: self.manual_assign_selected(d)).pack(side="left", padx=3)\n        ttk.Button(actions, text="Correct auto-allocation", command=lambda d=direction: self.correct_auto_allocation_selected(d)).pack(side="left", padx=3)\n        ttk.Button(actions, text="VAT / No VAT (this statement)", command=lambda d=direction: self.toggle_vat_selected(d)).pack(side="left", padx=3)\n        ttk.Button(actions, text="Clear assignment", command=lambda d=direction: self.clear_assignment_selected(d)).pack(side="left", padx=(12, 3))\n        ttk.Button(actions, text="Reset to saved rule", command=lambda d=direction: self.reset_selected_to_rule(d)).pack(side="left", padx=3)\n        recurring_tab = self.recurring_receipt_tab if direction == "RECEIPT" else self.recurring_pay_tab\n        ttk.Button(actions, text=f"Manage recurring {noun_plural}…", command=lambda t=recurring_tab: self.notebook.select(t)).pack(side="right", padx=3)\n\n        actions2 = ttk.Frame(controls); actions2.pack(fill="x", pady=(5,0))\n        ttk.Button(actions2, text="Toggle export selection", command=lambda d=direction: self.toggle_include_selected(d)).pack(side="left", padx=3)\n        ttk.Button(actions2, text="Select Auto-Allocated", command=lambda d=direction: self.select_auto_allocated_export(d)).pack(side="left", padx=(12,3))\n        ttk.Button(actions2, text="Select Manual Allocations", command=lambda d=direction: self.select_manual_allocated_export(d)).pack(side="left", padx=3)\n        ttk.Button(actions2, text="Select All", command=lambda d=direction: self.set_all_export(d, True)).pack(side="left", padx=3)\n        ttk.Button(actions2, text="Clear All", command=lambda d=direction: self.set_all_export(d, False)).pack(side="left", padx=3)\n'''

    new_main_actions = '''        actions = ttk.LabelFrame(controls, text="Allocation tools"); actions.pack(fill="x", pady=(2, 4))\n        help_action(actions, "Save rule from selected", lambda d=direction: self.assign_rule_selected(d), "Create or update a saved rule from the selected transaction. Matching transactions can then be allocated automatically.")\n        help_action(actions, "Assign once", lambda d=direction: self.manual_assign_selected(d), "Allocate only the selected transaction in this statement. This does not create or change a saved rule.")\n        help_action(actions, "Correct auto-allocation", lambda d=direction: self.correct_auto_allocation_selected(d), "Fix an automatically allocated transaction. You can apply the correction only to this statement or update the saved rule.")\n        help_action(actions, "VAT / No VAT", lambda d=direction: self.toggle_vat_selected(d), "Toggle VAT for the selected transaction(s) in this statement.")\n        help_action(actions, "Clear assignment", lambda d=direction: self.clear_assignment_selected(d), "Remove the current allocation from the selected transaction(s) in this statement.", padx=(12, 3))\n        help_action(actions, "Reset to saved rule", lambda d=direction: self.reset_selected_to_rule(d), "Discard statement-only changes and reapply the matching saved allocation rule.")\n        recurring_tab = self.recurring_receipt_tab if direction == "RECEIPT" else self.recurring_pay_tab\n        help_action(actions, f"Manage recurring {noun_plural}…", lambda t=recurring_tab: self.notebook.select(t), "Open the recurring transactions screen where each recurring identity can be reviewed or allocated separately.", side="right")\n\n        actions2 = ttk.LabelFrame(controls, text="Export selection"); actions2.pack(fill="x", pady=(4,0))\n        ttk.Label(actions2, text="Quick-select buttons ADD matching rows to your current ticks. Use Clear All to start over.", foreground="#555555").pack(anchor="w", padx=6, pady=(3, 1))\n        selection_row = ttk.Frame(actions2); selection_row.pack(fill="x", padx=3, pady=(0, 4))\n        help_action(selection_row, "Toggle selected", lambda d=direction: self.toggle_include_selected(d), "Toggle the export tick only for the transaction rows you currently selected in the table.")\n        help_action(selection_row, "Add Auto-Allocated", lambda d=direction: self.select_auto_allocated_export(d), "Add all successfully auto-allocated transactions to the current export selection. Existing manual selections stay ticked.", padx=(12, 3))\n        help_action(selection_row, "Add Manual Allocations", lambda d=direction: self.select_manual_allocated_export(d), "Add all successfully manually allocated or manually corrected transactions to the current export selection. Existing automatic selections stay ticked.")\n        help_action(selection_row, "Select All", lambda d=direction: self.set_all_export(d, True), "Tick every transaction in this payment/receipt list for export.")\n        help_action(selection_row, "Clear All", lambda d=direction: self.set_all_export(d, False), "Untick every transaction in this payment/receipt list so you can start a new export selection.")\n'''
    s = replace_once(s, old_main_actions, new_main_actions, 'main user-friendly actions')

    old_recurring_actions = '''        actions = ttk.Frame(tab, padding=(8, 0, 8, 7)); actions.pack(fill="x")\n        ttk.Button(actions, text=f"Assign selected {noun} once", command=lambda d=direction: self.assign_recurring_transaction_once(d)).pack(side="left", padx=3)\n        ttk.Button(actions, text="Correct auto-allocation", command=lambda d=direction: self.correct_recurring_auto_allocation(d)).pack(side="left", padx=3)\n        ttk.Button(actions, text="Save / edit identity rule", command=lambda d=direction: self.assign_recurring_rule(d)).pack(side="left", padx=3)\n        ttk.Button(actions, text="Toggle export selection", command=lambda d=direction: self.toggle_recurring_include_selected(d)).pack(side="left", padx=(12, 3))\n        ttk.Button(actions, text="Clear transaction assignment", command=lambda d=direction: self.clear_recurring_transaction_assignment(d)).pack(side="left", padx=3)\n        ttk.Button(actions, text="Reset transaction to saved rule", command=lambda d=direction: self.reset_recurring_transaction_to_rule(d)).pack(side="left", padx=3)\n        ttk.Button(actions, text=f"Show selected in {noun_plural.title()}", command=lambda d=direction: self.show_recurring_in_transactions(d)).pack(side="left", padx=(12, 3))\n\n        actions2 = ttk.Frame(tab, padding=(8, 0, 8, 7)); actions2.pack(fill="x")\n        ttk.Button(actions2, text="Select auto-allocated recurring", command=lambda d=direction: self.select_auto_allocated_export(d, True)).pack(side="left", padx=3)\n        ttk.Button(actions2, text="Select manual allocations", command=lambda d=direction: self.select_manual_allocated_export(d, True)).pack(side="left", padx=3)\n        ttk.Button(actions2, text="Select all recurring for export", command=lambda d=direction: self.set_all_recurring_export(d, True)).pack(side="left", padx=3)\n        ttk.Button(actions2, text="Clear all recurring from export", command=lambda d=direction: self.set_all_recurring_export(d, False)).pack(side="left", padx=3)\n        ttk.Label(actions2, text="Tip: click the ☐ / ☑ box on an individual transaction to change only that transaction.", foreground="#555555").pack(side="left", padx=18)\n        ttk.Button(actions2, text="Expand all", command=lambda d=direction: self.set_recurring_expanded(d, True)).pack(side="right", padx=3)\n        ttk.Button(actions2, text="Collapse all", command=lambda d=direction: self.set_recurring_expanded(d, False)).pack(side="right", padx=3)\n'''

    new_recurring_actions = '''        actions = ttk.LabelFrame(tab, text="Recurring allocation tools", padding=(8, 4, 8, 6)); actions.pack(fill="x", padx=8, pady=(0, 5))\n        help_action(actions, f"Assign selected {noun} once", lambda d=direction: self.assign_recurring_transaction_once(d), "Allocate only the selected recurring transaction. Other transactions in the same recurring group are not changed.")\n        help_action(actions, "Correct auto-allocation", lambda d=direction: self.correct_recurring_auto_allocation(d), "Correct the selected recurring transaction. If you update the saved rule, matching rows remain automatic allocations.")\n        help_action(actions, "Save / edit identity rule", lambda d=direction: self.assign_recurring_rule(d), "Create or edit the saved allocation rule for this recurring identity so future matching CSV transactions can allocate automatically.")\n        help_action(actions, "Toggle selected export", lambda d=direction: self.toggle_recurring_include_selected(d), "Toggle the export tick for the currently selected recurring transaction only.", padx=(12, 3))\n        help_action(actions, "Clear assignment", lambda d=direction: self.clear_recurring_transaction_assignment(d), "Remove the allocation from the selected recurring transaction in this statement.")\n        help_action(actions, "Reset to saved rule", lambda d=direction: self.reset_recurring_transaction_to_rule(d), "Discard statement-only changes for the selected recurring transaction and reapply its saved rule.")\n        help_action(actions, f"Show in {noun_plural.title()}", lambda d=direction: self.show_recurring_in_transactions(d), "Jump back to the main transaction list and show the selected recurring transaction.", padx=(12, 3))\n\n        actions2 = ttk.LabelFrame(tab, text="Quick select for export", padding=(8, 4, 8, 6)); actions2.pack(fill="x", padx=8, pady=(0, 7))\n        ttk.Label(actions2, text="These buttons are additive: click Auto and Manual to keep BOTH groups ticked together. Clear only when you want to start over.", foreground="#555555").pack(anchor="w", pady=(0, 3))\n        recurring_selection_row = ttk.Frame(actions2); recurring_selection_row.pack(fill="x")\n        help_action(recurring_selection_row, "Add Auto-Allocated", lambda d=direction: self.select_auto_allocated_export(d, True), "Add recurring transactions allocated automatically by saved rules. Existing manual selections remain ticked.")\n        help_action(recurring_selection_row, "Add Manual Allocations", lambda d=direction: self.select_manual_allocated_export(d, True), "Add recurring transactions that were allocated or corrected manually. Existing automatic selections remain ticked.")\n        help_action(recurring_selection_row, "Select All Recurring", lambda d=direction: self.set_all_recurring_export(d, True), "Tick every recurring transaction for export.")\n        help_action(recurring_selection_row, "Clear Recurring", lambda d=direction: self.set_all_recurring_export(d, False), "Untick every recurring transaction so you can build a new selection.")\n        help_action(recurring_selection_row, "Expand all", lambda d=direction: self.set_recurring_expanded(d, True), "Expand every recurring group so its individual transactions are visible.", side="right")\n        help_action(recurring_selection_row, "Collapse all", lambda d=direction: self.set_recurring_expanded(d, False), "Collapse every recurring group to show only the group headings.", side="right")\n'''
    s = replace_once(s, old_recurring_actions, new_recurring_actions, 'recurring user-friendly actions')

    # Give the most important amount-based rule choices inline hover explanations too.
    s = replace_once(
        s,
        '        self.amount_action.grid(row=1, column=4, padx=(6,0), sticky="ew")\n        self.amount_action.bind("<<ComboboxSelected>>", lambda e: self._amount_state())\n',
        '        self.amount_action.grid(row=1, column=4, padx=(6,0), sticky="ew")\n        help_icon(amount_box, "Automatically allocate applies the alternative GL/description immediately. Review each qualifying transaction leaves matching amounts for you to allocate individually.").grid(row=1, column=5, padx=(4,0), sticky="w")\n        self.amount_action.bind("<<ComboboxSelected>>", lambda e: self._amount_state())\n',
        'amount action help icon',
    )
    s = replace_once(
        s,
        '        self.amount_account.grid(row=2, column=2, columnspan=3, sticky="ew", pady=(7,0))\n',
        '        self.amount_account.grid(row=2, column=2, columnspan=3, sticky="ew", pady=(7,0))\n        help_icon(amount_box, "General ledger account used only when the amount condition is met and the action is Automatically allocate.").grid(row=2, column=5, padx=(4,0), pady=(7,0), sticky="w")\n',
        'alternative GL help icon',
    )
    s = replace_once(
        s,
        '        self.amount_description.grid(row=3, column=2, columnspan=3, sticky="ew", pady=(7,0))\n',
        '        self.amount_description.grid(row=3, column=2, columnspan=3, sticky="ew", pady=(7,0))\n        help_icon(amount_box, "Optional Pastel description used for the amount-condition branch. Leave blank to keep the normal rule description.").grid(row=3, column=5, padx=(4,0), pady=(7,0), sticky="w")\n',
        'alternative description help icon',
    )

    p.write_text(s, encoding="utf-8")
    print(f"Transformed {p} to v1.11.15 with clearer grouped controls and hover help")


if __name__ == "__main__":
    main(sys.argv[1])
